package com.disasterrelief.controller;
import java.util.List; import com.disasterrelief.dto.VolunteerRequest; import com.disasterrelief.model.Volunteer; import com.disasterrelief.service.ReliefService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/volunteers") public class VolunteerController { private final ReliefService s; public VolunteerController(ReliefService s){this.s=s;} @GetMapping public List<Volunteer> all(){return s.volunteers();} @GetMapping("/{id}") public Volunteer one(@PathVariable Long id){return s.volunteer(id);} @PostMapping public ResponseEntity<Volunteer> create(@Valid @RequestBody VolunteerRequest x){return ResponseEntity.status(HttpStatus.CREATED).body(s.saveVolunteer(x,null));} @PutMapping("/{id}") public Volunteer update(@PathVariable Long id,@Valid @RequestBody VolunteerRequest x){return s.saveVolunteer(x,id);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.deleteVolunteer(id);} }
